    'CD163', 'CD68', 'FCGBP', 'STAB1', 'LYZ', 'CD14', 'MS4A1', 'CD79A', 
    'CD3D', 'CD3E', 'CD8A', 'CD4', 'TRAC', 'NCAM1', 'NKG7', 'GNLY',
    'HBB', 'HBA1', 'HBA2', 'CD74', 'HLA-A', 'HLA-B', 'HLA-C', 'B2M',
    'CXCL8', 'CXCL10', 'CCL2', 'CCL5', 'IL1B', 'TNF'
}

# Calculate mean expression per cluster for these markers
